import{_ as t,c as a,o,ae as r}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Add/Remove Search or Filter Functionality","description":"Add/Remove Search or Filter Functionality","frontmatter":{"title":"Add/Remove Search or Filter Functionality","description":"Add/Remove Search or Filter Functionality"},"headers":[],"relativePath":"guide/styling-design/add-or-remove-search-or-filter-functionality.md","filePath":"guide/styling-design/add-or-remove-search-or-filter-functionality.md"}'),i={name:"guide/styling-design/add-or-remove-search-or-filter-functionality.md"};function n(l,e,s,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="add-remove-search-or-filter-functionality" tabindex="-1">Add/Remove Search or Filter Functionality <a class="header-anchor" href="#add-remove-search-or-filter-functionality" aria-label="Permalink to &quot;Add/Remove Search or Filter Functionality&quot;">​</a></h1><p><strong>Search</strong> or <strong>Filter</strong> <strong>functionality</strong> can be a lifesaver if your table contains large data. It&#39;s a handy option even if your table is short and summarized. On the other hand, sometimes you might feel like removing the search option. The search bar is set by default at the top of the table. But here is how you can remove/add this functionality with just a click and without any kind of coding.</p><h2 id="search-and-filter-data-tables" tabindex="-1">Search and Filter Data Tables <a class="header-anchor" href="#search-and-filter-data-tables" aria-label="Permalink to &quot;Search and Filter Data Tables&quot;">​</a></h2><ul><li>Select the table you want to add/remove the search option from.</li><li>Now, navigate to the <strong>Table Design</strong> Tab. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-enable-filter-and-search-1024x481.webp" alt="New Ui enable filter and search"></li><li>Toggle the **Enable the visitor to filter or search the table **option if you want the audience to filter and search data table. And toggle off if you don&#39;t want the search bar.</li></ul><h2 id="disable-frontend-search-for-a-specific-column" tabindex="-1"><strong>Disable Frontend Search for a Specific Column</strong> <a class="header-anchor" href="#disable-frontend-search-for-a-specific-column" aria-label="Permalink to &quot;**Disable Frontend Search for a Specific Column**&quot;">​</a></h2><p>If you want to disable frontend search for a specific column to the Table Rows and open the column you want to hide from frontend filtering and searching. From that column&#39;s <strong>Advanced Settings</strong>, just toggle the checkboxes for &quot;Sortable&quot; and &quot;Filterable&quot;. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-enable-sorting-filtering-1024x613.webp" alt="New Ui disable sorting filtering"> This is how you can <strong>add or remove Search / Filter functionality</strong> in Ninja Tables plugin.</p>',6)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
